def _replace_once(page: str, old: str, new: str, label: str) -> str:
    if page.count(old) != 1:
        raise ValueError(f"FLUX.2 Max reference template drift: {label}")
    return page.replace(old, new, 1)


def _replace_meta(page: str, key: str, value: str) -> str:
    pattern = r'(<meta (?:name|property)="' + re.escape(key) + r'" content=")[^"]*(" />)'
    updated, count = re.subn(
        pattern,
        lambda match: match.group(1) + escape(value, quote=True) + match.group(2),
        page,
        count=1,
    )
    if count != 1:
        raise ValueError("FLUX.2 Max meta tag missing: " + key)
    return updated


def enrich_flux2_max_page(page: str) -> str:
    """Enrich the catalog output. Stable, idempotent and fail-fast on template drift."""
    if 'data-flux2-max-guide' in page:
        return page
    if f'<link rel="canonical" href="{CANONICAL}"' not in page:
        raise ValueError("FLUX.2 Max canonical changed")

    page, count = re.subn(
        r"<title>.*?</title>",
        "<title>" + escape(TITLE) + "</title>",
        page,
        count=1,
    )
    if count != 1:
        raise ValueError("FLUX.2 Max title missing")

    for key, value in (
        ("description", DESCRIPTION),
        ("og:title", TITLE),
        ("og:description", DESCRIPTION),
        ("twitter:title", TITLE),
        ("twitter:description", DESCRIPTION),
    ):
        page = _replace_meta(page, key, value)

    page = _replace_once(
        page, _TITLE_ANCHOR,
        "<h1>FLUX.2 Max<br><span>Image generation, API &amp; pricing.</span></h1>",
        "H1",
    )
    page = _replace_once(
        page, _HERO_ANCHOR,
        "<p>" + escape(HERO) + "</p>",
        "hero introduction",
    )
    for old, new in (
        ('<div><strong>Not published</strong><span>context not published</span></div>',
         '<div><strong>4 MP</strong><span>maximum output resolution</span></div>'),
        ('<div><strong>Not published</strong><span>max output</span></div>',
         '<div><strong>8 images</strong><span>API reference limit</span></div>'),
        ('<div><span>CONTEXT WINDOW</span><strong>Not published</strong></div>',
         '<div><span>MAX OUTPUT RESOLUTION</span><strong>4 MP</strong></div>'),
        ('<div><span>MAX OUTPUT</span><strong>Not published</strong></div>',
         '<div><span>REFERENCE INPUTS</span><strong>Up to 8</strong><small>BFL API; 10 in Playground</small></div>'),
        ('<div><span>KNOWLEDGE CUTOFF</span><strong>Not published</strong></div>',
         '<div><span>MODES</span><strong>Generate + edit</strong><small>text prompt and image references</small></div>'),
        ('<div><span>OUTPUT RATE</span><strong>—</strong><small>official-paid</small></div>',
         '<div><span>ADDITIONAL OUTPUT MP</span><strong>+$0.03</strong><small>reference input: $0.03 per billed MP</small></div>'),
        ('<article><span>REASONING</span><h3>Not published</h3><p>Only provider-documented reasoning controls are shown; missing controls remain unpublished rather than inferred.</p></article>',
         '<article><span>GROUNDING SEARCH</span><h3>Max only</h3><p>Can retrieve current web context when prompted. Verify any factual details independently.</p></article>'),
        ('<p>SXF preserves the provider-published native billing basis. Only calculator-eligible generative token models enter token-cost arithmetic; specialist units and input-only embeddings remain visible without forced conversion.</p>',
         '<p>Image-generation billing is tied to whole billed output megapixels and billed reference-image input. A token-price calculator cannot estimate an edited image accurately. See the detailed pricing examples below.</p>'),
    ):
        page = _replace_once(page, old, new, old[:35])

    schema_match = re.search(r'(<script type="application/ld\+json">)(.*?)(</script>)', page, re.DOTALL)
    if schema_match is None:
        raise ValueError("FLUX.2 Max JSON-LD missing")
    graph = json.loads(schema_match.group(2))
    if graph.get("@context") != "https://schema.org":
        raise ValueError("FLUX.2 Max schema context changed")
    article = next((entry for entry in graph["@graph"] if entry.get("@type") == "TechArticle"), None)
    if article is None:
        raise ValueError("FLUX.2 Max TechArticle missing")
    article["headline"] = TITLE.removesuffix(" | SXF / AI")
    article["description"] = DESCRIPTION
    article["citation"] = SOURCES
    article["mainEntityOfPage"] = {"@type": "WebPage", "@id": CANONICAL}
    article["author"] = {"@type": "Organization", "name": "SXF / AI", "url": "https://sxf.si/"}
    article["publisher"] = {"@type": "Organization", "name": "SXF / AI", "url": "https://sxf.si/"}
    article["keywords"] = [
        "FLUX.2 Max", "FLUX.2 [max]", "FLUX.2 Max pricing",
        "FLUX.2 Max API", "FLUX.2 Max image editing", "FLUX.2 Max vs Pro",
    ]
    graph["@graph"].append({
        "@type": "FAQPage",
        "@id": CANONICAL + "#faq",
        "url": CANONICAL + "#flux2-max-faq",
        "mainEntity": [
            {"@type": "Question", "name": question, "acceptedAnswer": {"@type": "Answer", "text": answer}}
            for question, answer in FAQS
        ],
    })
    jsonld = json.dumps(graph, ensure_ascii=False, separators=(",", ":"))
    page = page[:schema_match.start(2)] + jsonld + page[schema_match.end(2):]

    return _replace_once(
        page, _CAVEATS, SECTIONS + FAQ_HTML + "\n\n        " + _CAVEATS, "insertion point"
    )
